class Solution {
    public int findMinArrowShots(int[][] points) {
        int count = 0;
        boolean[] burst = new boolean[points.length];
        int remaining = points.length;
        while (remaining > 0) {
            int earliest = -1;
            for (int index = 0; index < points.length; index++) {
                if (!burst[index] && (earliest == -1 || points[index][1] < points[earliest][1])) {
                    earliest = index;
                }
            }
            int arrow = points[earliest][1];
            count++;
            for (int index = 0; index < points.length; index++) {
                if (!burst[index] && points[index][0] <= arrow && arrow <= points[index][1]) {
                    burst[index] = true;
                    remaining--;
                }
            }
        }
        return count;
    }
}

